"use client";
import { conversationLocalStorage as localStorage, conversationSessionStorage as sessionStorage } from "../../lib/recovery-session";

import { startIndependentRecovery, checkRecoveryAdmission } from "../../lib/recovery-session";
import { temporaryStateMessage } from "../../lib/temporary-state-error";

import { maintenanceMessage } from "../../lib/maintenance-result";

import { TEMPORARY_STATE_KEY, DEVICE_USER_KEY } from "../../lib/device-conversation";
import {
  useEffect,
  useState,
} from "react";

import {
  supabase,
} from "../../lib/supabase";

import {
  registerPushSubscription,
  sendTestPushNotification,
} from "../../lib/push-notifications";

type ChatMessage = {
  role: "misaki" | "user";
  text: string;
  requestId?: string;
};

type DailyUsage = {
  date: string;
  count: number;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type Plan =
  | "free"
  | "premium";

type UsageRpcResult = {
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type ApiUsage = {
  messageCount?: number;
  remaining?: number;
  isPremium?: boolean;
};

const STORAGE_KEY =
  "misaki-chat-history";

const MEMORY_KEY =
  "misaki-long-term-memory";

const RELATIONSHIP_KEY =
  "misaki-relationship-points";

const MISAKI_TODAY_MEMORY_KEY =
  "misaki-today-memory";

const MAX_MESSAGES = 60;

// 無料版は1日20往復まで
const FREE_DAILY_LIMIT = 20;

const INITIAL_MESSAGES:
  ChatMessage[] = [];



function getJapanDateKey() {
  return new Date()
    .toLocaleDateString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",
      }
    );
}

function getJapanCurrentTime() {
  return new Date()
    .toLocaleString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",

        weekday:
          "short",

        hour:
          "2-digit",

        minute:
          "2-digit",

        hour12:
          false,
      }
    );
}

function createEmptyTodayMemory():
  MisakiTodayMemory {
  return {
    date:
      getJapanDateKey(),

    items: [],
  };
}

function isPremiumActive(
  plan:
    | string
    | null
    | undefined,

  premiumUntil:
    | string
    | null
    | undefined
) {
  if (
    plan !==
    "premium"
  ) {
    return false;
  }

  if (
    !premiumUntil
  ) {
    return true;
  }

  const expiresAt =
    new Date(
      premiumUntil
    ).getTime();

  if (
    !Number.isFinite(
      expiresAt
    )
  ) {
    return false;
  }

  return (
    expiresAt >
    Date.now()
  );
}

function getFirstRpcRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(
      value
    ) &&
    value.length >
      0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value ===
      "object"
  ) {
    return value as T;
  }

  return null;
}

export default function ChatPage() {
